"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8682],{38682:n=>{n.exports=JSON.parse('{"schemaVersion":1,"locale":"ru","slug":"gajd-2-pds","title":"Гайд 2. Программа долгосрочных сбережений: Запуск ПДС без риска потери субсидий","sourceFingerprint":"4f5e8d968ad6e0eee8e3f37d50ab7f315a4d8af328d029c8ac4b3cd6313124e8","blocks":[{"id":"b001","markdown":"*Том II: Защита капитала: 20 лет против инфляции*  \\n*Раздел: Практические руководства инвестора*"},{"id":"b002","markdown":"# Практикум: Запуск Программы долгосрочных сбережений без риска потери господдержки"},{"id":"b003","markdown":"> \xabЛюбая государственная субсидия эффективна лишь тогда, когда инвестор точно знает скрытые условия договора и не позволяет бюрократическим ловушкам аннулировать накопленный результат\xbb."},{"id":"b004","markdown":"Программа долгосрочных сбережений (ПДС) представляет собой гибридный инструмент: гражданин аккумулирует капитал через аккредитованный НПФ, а государственный бюджет на протяжении первых десяти лет софинансирует взносы на сумму вплоть до 36 000 ₽ ежегодно. Ниже представлен строгий семиэтапный алгоритм, позволяющий забрать положенную премию и налоговые преференции в полном объеме."},{"id":"b005","markdown":"## Пошаговый регламент подключения"},{"id":"b006","markdown":"### Этап 1. Аудит целесообразности участия\\nПрежде чем открывать счет, проверьте соответствие трем критериям:\\n1. **Горизонт планирования:** свободные средства не понадобятся вам на текущие нужды минимум 15 лет (либо до момента наступления возраста 55 лет для женщин и 60 лет для мужчин).\\n2. **Уровень официального заработка:** наибольшая отдача достигается при ежемесячном доходе до 150 000 ₽. Если доход превышает данную планку, государство субсидирует лишь 25 копеек на каждый внесенный рубль, что существенно снижает относительную доходность инструмента.\\n3. **Наличие ближнего резерва:** краткосрочные цели на дистанции до 5 лет уже закрыты вкладами, накопительными счетами и балансом ИИС-3."},{"id":"b007","markdown":"> **Маркер внимания:** налоговая база для социального вычета ограничена лимитом 400 000 ₽ в год суммарно для ИИС третьего типа, пенсионных соглашений и ПДС. Если вы направляете предельные 400 000 ₽ на ИИС-3, забрать дополнительный возврат НДФЛ через ПДС не удастся (но право на государственное софинансирование до 36 000 ₽ в год сохраняется в полном объеме)."},{"id":"b008","markdown":"### Этап 2. Сравнение и фильтрация операторов (НПФ)\\nОформление происходит через негосударственные пенсионные фонды. Обязательный чек-лист проверки организации:\\n* **Лицензирование регулятором:** убедитесь в наличии действующей записи в реестре субъектов финансового рынка на портале Банка России (`cbr.ru`).\\n* **Гарантийная система АСВ:** наличие фонда в государственной системе гарантирования прав участников (страховое покрытие капитала по ПДС составляет 2,8 млн ₽).\\n* **Ретроспективная доходность:** изучайте результаты управления активами на интервале от 5–7 лет по официальным сводкам регулятора. Доходность за единственный удачный год не является репрезентативной.\\n* **Цифровая инфраструктура:** оцените удобство мобильного приложения фонда либо интеграцию с вашим повседневным банковским кабинетом."},{"id":"b009","markdown":"### Этап 3. Юридическое оформление договора\\nОформить соглашение можно онлайн через единый портал \xabГосуслуги\xbb (механизм доступен с 1 октября 2025 года), непосредственно на веб-ресурсе выбранного НПФ либо в отделении банка-агента."},{"id":"b010","markdown":"> **Маркер внимания:** ранее сформированную накопительную пенсию (ОПС) разрешено перевести в тело ПДС. Перенесенный пенсионный остаток начнет инвестироваться фондом, однако он не признается свежим взносом и не дает права на получение государственной доплаты за текущий период."},{"id":"b011","markdown":"### Этап 4. Расчет и запуск оптимальных взносов\\nМинимальная граница для начисления доплаты — **2 000 ₽ за календарный год**. Если внести меньше, господдержка за расчетный период сгорает."},{"id":"b012","markdown":"Чтобы забирать предельные **36 000 ₽ в год**, опирайтесь на формулу вашей зарплатной вилки:"},{"id":"b013","markdown":"| Среднемесячный официальный доход | Необходимый годовой взнос | Ежемесячный платеж | Ежегодная доплата от государства |\\n| :--- | :--- | :--- | :--- |\\n| **До 80 000 ₽** | 36 000 ₽ | 3 000 ₽ | 36 000 ₽ (коэффициент 1:1) |\\n| **От 80 000 до 150 000 ₽** | 72 000 ₽ | 6 000 ₽ | 36 000 ₽ (коэффициент 1:2) |\\n| **Свыше 150 000 ₽** | 144 000 ₽ | 12 000 ₽ | 36 000 ₽ (коэффициент 1:4) |"},{"id":"b014","markdown":"*Практическое решение:* настройте регулярное списание по автоплатежу на следующий день после выплаты зарплаты. Вносить суммы ниже расчетных лимитов не запрещено — государство рассчитает доплату строго пропорционально внесенным деньгам."},{"id":"b015","markdown":"### Этап 5. Контроль перечисления субсидии\\nСпециальных запросов направлять не требуется: НПФ централизованно отчитывается перед оператором программы. Государственные деньги за предшествующий расчетный год зачисляются на счет в летний период (традиционно в интервале с мая по июль). Ваша задача — в середине лета открыть выписку и проверить поступление. При отсутствии транзакции подается официальный запрос в службу поддержки фонда."},{"id":"b016","markdown":"### Этап 6. Оформление налогового возврата\\nВозврат НДФЛ оформляется по аналогичной с ИИС схеме: через кабинет налогоплательщика на сайте ФНС с помощью декларации 3-НДФЛ либо по упрощенному заявлению на основе данных, переданных оператором."},{"id":"b017","markdown":"### Этап 7. Мониторинг досрочного расторжения\\nПреждевременное прекращение договора без регламентированных законом оснований приводит к полной отмене государственной поддержки и возврату лишь так называемой \xabвыкупной суммы\xbb, рассчитанной с понижающим дисконтом по правилам фонда."},{"id":"b018","markdown":"*Легитимные исключения для изъятия всей суммы без штрафов:*\\n* Необходимость оплаты дорогостоящих медицинских процедур (по утвержденному перечню).\\n* Смерть кормильца семьи."},{"id":"b019","markdown":"*Примечание:* Смена одного НПФ на другой с переводом средств не аннулирует накопленное софинансирование."},{"id":"b020","markdown":"## \uD83E\uDDEE Расчёт на полях тетради"},{"id":"b021","markdown":"Разберем сценарий инженера Михаила (официальный заработок — 75 000 ₽ в месяц).\\n* **Ежемесячный транш:** 3 000 ₽ (36 000 ₽ за год).\\n* **Государственное софинансирование:** 36 000 ₽ в год (коэффициент 1 к 1).\\n* **Налоговый возврат по ставке 13%:** 36 000 ₽ \xd7 13% = 4 680 ₽.\\n* **Итого за 1 год личных вложений в 36 000 ₽:** инвестор получает на счете 72 000 ₽ плюс 4 680 ₽ возвратом на банковскую карту (без учета инвестиционного процента НПФ).\\n* **Суммарно за 10 лет действия программы поддержки:** чистая доплата из бюджета достигнет **360 000 ₽** исключительно за счет дисциплинированного автоплатежа."}],"terms":[{"id":"npf-operator","term":"Оператор ПДС","definition":"негосударственный пенсионный фонд, ведущий счета программы сбережений."},{"id":"strakhovka-pds","term":"Страховка ПДС 2,8 млн ₽","definition":"государственная гарантия сохранности средств в ПДС через АСВ."},{"id":"dorogostoyashchee-lechenie","term":"Особая жизненная ситуация","definition":"случай (лечение), позволяющий досрочно забрать деньги из ПДС без штрафа."}],"quizzes":[{"id":"q1","q":"Каков максимальный размер государственного софинансирования взносов в Программу долгосрочных сбережений (ПДС) в год?","options":["До 36 000 рублей в год в течение первых 10 лет участия","Не более 5 000 рублей один раз при открытии договора","Государство удваивает любую внесённую сумму без ограничений"],"correct":0,"explanation":"Законодательство о ПДС фиксирует предел государственной субсидии на уровне до 36 000 рублей в год."},{"id":"q2","q":"Каков лимит страхования сбережений в ПДС государственной системой страхования АСВ?","options":["1,4 млн рублей, как по обычному вкладу","2,8 млн рублей (включая личные взносы, господдержку и инвестиционный доход)","Средства в негосударственных пенсионных фондах вообще не страхуются"],"correct":1,"explanation":"Государственная страховка АСВ для счетов ПДС составляет 2,8 млн рублей — ровно вдвое выше банковского вклада."},{"id":"q3","q":"В какой особой жизненной ситуации закон разрешает досрочно забрать средства из ПДС без потери права на софинансирование?","options":["Покупка нового автомобиля или турпоездка","Оплата дорогостоящего лечения по установленному Правительством РФ перечню или потеря кормильца","Любое желание инвестора при подаче заявления за 3 дня"],"correct":1,"explanation":"Особая жизненная ситуация (тяжёлое лечение из перечня Правительства) позволяет досрочно изъять средства без потери субсидий."}],"officialSources":[]}')}}]);